function NavLink({
  active,
  item,
  onNavigate,
}: {
  active: boolean
  item: NavItem
  onNavigate?: (title: string) => void
}) {
  return (
    <SidebarMenuItem>
      <SidebarMenuButton
        /* Two differences from the primitive's defaults, both as the app has
           them: hover lands on the neutral `accent` rather than the purple
           `sidebar-accent`, and the active item carries a hairline of its own
           foreground so the filled pill reads as a border, not just a wash. */
        className="border border-transparent hover:bg-accent hover:text-accent-foreground data-active:border-sidebar-accent-foreground/10"
        isActive={active}
        tooltip={item.title}
        onClick={() => onNavigate?.(item.title)}
      >
        <item.icon />
        {/* Closing to the rail fades the label out rather than clipping it. */}
        <span className="truncate transition-opacity duration-200 ease-out-cubic group-data-[collapsible=icon]:opacity-0 motion-reduce:transition-none">
          {item.title}
        </span>
      </SidebarMenuButton>
      {/* `rounded-sm` in place of the primitive's `rounded-md` and `right-2` in
          place of `right-1`, both as the app has them.

          The glyph size is deliberately NOT the app's `[&>svg]:size-full`. That
          class works there because its plus is a hand-drawn 20×20 icon whose
          path spans only 6.5→13.5, so filling the box still draws a 7px plus.
          Ours is HugeIcons' PlusSignIcon, whose ink fills 16 of its 24 viewBox
          units — the same class drew a 12px plus, nearly twice the app's.
          `size-2.5` renders it at 10px, putting the drawn plus at 6.7px. */}
      {item.action ? (
        <SidebarMenuAction
          aria-label={item.action}
          className="top-1.5 right-2 rounded-sm border border-input bg-background text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-2.5"
        >
          <NewItemIcon />
        </SidebarMenuAction>
      ) : null}
    </SidebarMenuItem>
  )
}

/**
 * Collapsed to the icon rail there is no room for a section label, so the
 * groups are forced open and the label — the only thing that could close them —
 * is disabled.
 */
function NavGroup({
  active,
  defaultOpen,
  items,
  label,
  onNavigate,
}: {
  active: string
  defaultOpen: boolean
  items: NavItem[]
  label: string
  onNavigate?: (title: string) => void
}) {
  const { state } = useSidebar()
  const isCollapsed = state === "collapsed"
  const [open, setOpen] = React.useState(defaultOpen)

  return (
    <Collapsible
      disabled={isCollapsed}
      onOpenChange={isCollapsed ? undefined : setOpen}
      open={isCollapsed || open}
    >
      <SidebarGroup>
        <SidebarGroupLabel asChild>
          <CollapsibleTrigger className="flex w-full cursor-pointer items-center justify-between hover:bg-accent/50">
            <span>{label}</span>
            <ChevronDownIcon
              className={cn(
                "transition-transform duration-200 ease-out-cubic motion-reduce:transition-none",
                open ? "rotate-0" : "-rotate-90",
              )}
            />
          </CollapsibleTrigger>
        </SidebarGroupLabel>
        <CollapsibleContent>
          <SidebarGroupContent>
            <SidebarMenu>
              {items.map((item) => (
                <NavLink
                  active={item.title === active}
                  item={item}
                  key={item.title}
                  onNavigate={onNavigate}
                />
              ))}
            </SidebarMenu>
          </SidebarGroupContent>
        </CollapsibleContent>
      </SidebarGroup>
    </Collapsible>
  )
}

/** Breadcrumb start, account end — the row every page in the app sits under. */
export function AppHeader({
  actions,
  scope,
  developers,
  trail,
  showSettings,
}: {
  /** Swaps "Developer Doc" for a Developers button that opens the
   *  Developers page — "open" when that page is the one showing. Off, the
   *  header is the one the app ships today. */
  developers?: "link" | "open"
  /** Sits first in the header's right-hand row — the admin view a
   *  superadmin is reading the page as. */
  scope?: React.ReactNode
  /** Replaces the account row entirely. The design-system page uses it to
   *  carry the way back to the index; a mockup leaves it off and gets the
   *  row the app itself shows. */
  actions?: React.ReactNode
  /** Crumbs after Home. The last is the page; earlier ones are links. */
  trail: readonly string[]
  showSettings?: boolean
}) {
  return (
    <header className="flex h-16 shrink-0 items-center justify-between gap-4 px-4">
      <Breadcrumb>
        {/* The app spaces its crumbs at 2.5; the primitive ships 1.5. */}
        <BreadcrumbList className="gap-2.5">
          <BreadcrumbItem>
            <BreadcrumbLink href="#">Home</BreadcrumbLink>
          </BreadcrumbItem>
          {trail.map((crumb, index) => (
            <React.Fragment key={crumb}>
              <BreadcrumbSeparator />
              <BreadcrumbItem>
                {index === trail.length - 1 ? (
                  <BreadcrumbPage>{crumb}</BreadcrumbPage>
                ) : (
                  <BreadcrumbLink href="#">{crumb}</BreadcrumbLink>
                )}
              </BreadcrumbItem>
            </React.Fragment>
          ))}
        </BreadcrumbList>
      </Breadcrumb>

      <div className="flex shrink-0 items-center gap-2">
        {scope}
        {actions ?? (
          <>
            {developers ? (
              <Button
                aria-current={developers === "open" ? "page" : undefined}
                size="sm"
                variant={developers === "open" ? "secondary" : "outline"}
              >
                <DeveloperDocsIcon />
                Developers
              </Button>
            ) : (
              <Button size="sm" variant="outline">
                <DeveloperDocsIcon />
                Developer Doc
              </Button>
            )}
            {/* The same allowlist the nav reads. The app has this gear on its own
            check today, which is how an admin gets a second dead end to the
            page the sidebar already sent them to. */}
            {showSettings ? (
              <Button
                aria-label="Global settings"
                size="icon-sm"
                variant="outline"
              >
                <SettingsIcon />
              </Button>
            ) : null}
            {/* Wrapped, rather than given `self-center`: the primitive ships
            `data-vertical:self-stretch`, and an attribute variant outranks a
            plain utility, so the rule stretched to the 28px row, got held to
            h-4, and settled at the top of it — 6px above the centre the buttons
            and the avatar share. Inside a wrapper of its own the flex line is
            the rule's own height, so stretching changes nothing and the wrapper
            is what the header centres. */}
            <div className="flex items-center">
              <Separator className="mx-1 h-4" orientation="vertical" />
            </div>
            {/* A rounded square at the same radius and height as the two buttons,
            not a circle. The app's account button is Clerk's, and Clerk does not
            inherit the app's CSS vars — so the real header sets its avatar
            radius to a 0.625rem literal, which is `--radius`, which is
            `rounded-lg`. A circle here is the one thing in this row that would
            not be in the app. `after:` and the fallback carry the primitive's
            own `rounded-full`, so both have to be squared off with it. */}
            <Avatar className="size-7 rounded-lg after:rounded-lg">
              <AvatarFallback className="rounded-lg">TA</AvatarFallback>
            </Avatar>
          </>
        )}
      </div>
    </header>
  )
}

export function AppShell({
  active,
  scope,
  developers,
  underShell = true,
  breadcrumb,
  hiddenItems,
  onNavigate,
  children,
}: {
  /** Title of the sidebar item this screen lives under, e.g. "Personas". */
  active: string
  /** The admin view, in the top bar. Only a superadmin sees one. */
  scope?: React.ReactNode
  /** The Developers button in the top bar, in place of "Developer Doc". */
  developers?: "link" | "open"
  /** Whether the mockup shell's header sits above, which the sidebar has to
   *  clear. Off when the app is shown inside a frame on its own. */
  underShell?: boolean
  /** Crumbs after Home; a bare string is a single one. Defaults to `active`. */
  breadcrumb?: string | readonly string[]
  /**
   * Nav item titles this viewer's role cannot open, so the menu holds only
   * what they can reach. Omit it and the nav is the full one, which is what
   * every other mockup wants.
   */
  hiddenItems?: readonly string[]
  /** Called with a nav item's title when it is clicked, so a mockup can make
   * the destinations it covers actually switch. Items it ignores stay inert. */
  onNavigate?: (title: string) => void
  children: React.ReactNode
}) {
  const hidden = new Set(hiddenItems ?? [])
  const groups = NAV.map((group) => ({
    ...group,
    items: group.items.filter((item) => !hidden.has(item.title)),
  })).filter((group) => group.items.length > 0)

  return (
    /* The app sizes its sidebar at 15rem; the shadcn primitive ships 16rem.
       Set here rather than in the primitive, which is generated. */
    <SidebarProvider
      className="min-h-0 flex-1"
      style={{ "--sidebar-width": "15rem" } as React.CSSProperties}
    >
      {/* The sidebar pins to the viewport as it does in the app, so it clears
          the mockup shell's own header rather than sliding under it. */}
      <Sidebar
        className={underShell ? "pt-12" : undefined}
        collapsible="icon"
        variant="inset"
      >
        <SidebarHeader className="px-2 pt-2 pb-1">
          <div className="flex items-center justify-between group-data-[state=collapsed]:justify-center">
            {/* 56×32 is the size the app's own header renders it at. */}
            <Image
              alt="sarj.ai"
              className="group-data-[state=collapsed]:hidden"
              height={32}
              priority
              src="/logo.png"
              width={56}
            />
            <SidebarTrigger className="size-8 rounded-md text-muted-foreground hover:bg-accent hover:text-foreground [&>svg]:size-5" />
          </div>
        </SidebarHeader>

        <SidebarContent>
          <SidebarGroup className="pt-2 pb-0">
            <SidebarGroupContent>
              <SidebarMenu>
                <NavLink
                  active={PLAYGROUND.title === active}
                  item={PLAYGROUND}
                  onNavigate={onNavigate}
                />
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>

          {groups.map((group, index) => (
            <React.Fragment key={group.label}>
              {/* The rail hides section labels, so a rule stands in for the
                  grouping those labels carry when the nav is open. */}
              {index > 0 ? (
                <div className="mx-2 my-1 hidden h-px shrink-0 bg-sidebar-border group-data-[collapsible=icon]:block" />
              ) : null}
              <NavGroup
                active={active}
                /* A closed group hiding the item the screen is on reads as the
                   nav having lost its place, so the active item's group opens
                   regardless of where the group would otherwise start. */
                defaultOpen={
                  group.defaultOpen ||
                  group.items.some((item) => item.title === active)
                }
                items={group.items}
                label={group.label}
                onNavigate={onNavigate}
              />
            </React.Fragment>
          ))}
        </SidebarContent>
      </Sidebar>

      <SidebarInset className="min-w-0 overflow-hidden">
        <AppHeader
          developers={developers}
          scope={scope}
          trail={
            breadcrumb === undefined
              ? [active]
              : typeof breadcrumb === "string"
                ? [breadcrumb]
                : breadcrumb
          }
          showSettings={!hidden.has("Global Settings")}
        />
        {/* No gutter here: the page owns its p-3 lg:p-4, matching the header. */}
        <div className="min-h-0 flex-1 overflow-auto">{children}</div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import { motion, useReducedMotion } from "motion/react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import * as React from "react"

import { ClearIcon, SearchIcon } from "@/components/shell/workspace-icons"
import { Card } from "@/components/ui/card"
import { Kbd } from "@/components/ui/kbd"
import {
  InputGroup,
  InputGroupAddon,
  InputGroupButton,
  InputGroupInput,
} from "@/components/ui/input-group"
import { DOCS_SECTIONS } from "@/lib/design-system/data"
import { docsHref } from "@/lib/design-system/nav"
import { MOCKUPS } from "@/lib/site/mockups-data"
import { REELS } from "@/lib/site/reels-data"
import { cn } from "@/lib/utils"

/**
 * The lab's search, folded into the nav as an icon until it is wanted.
 *
 * It replaces the field that lived in the design system's sidebar rail and went
 * with it. A permanent input in a floating pill would cost that width on every
 * page to serve the few visits that are a search; an icon costs one control and
 * opens into the same field.
 *
 * **Width is the animated property, deliberately.** The house rule is transform
 * and opacity only, and the usual substitute — `scaleX` on a pill — is wrong
 * here: this control grows about seven times its collapsed size, and a uniform
 * scale drags the corner radius out with it, so a 12px radius arrives as an
 * 84px lozenge that snaps back on settle. The reflow is confined to one leaf
 * inside a pill that is already `position: sticky` on its own layer, which is
 * the case the rule's own carve-out describes. Everything else here is opacity.
 *
 * The spring is the long-travel one rather than the snappy one: over 200px a
 * lightly damped spring overshoots far enough to read as a bounce, and a search
 * field that wobbles reads as a toy.
 */

/**
 * Collapsed to the icon button, and opened to the field. In pixels.
 *
 * `COLLAPSED` is `InputGroup`'s own `h-8`, so the closed control is a square
 * and reads as one icon button among the others in the pill rather than as a
 * field that has been squashed.
 */
const COLLAPSED = 32
const EXPANDED = 268

/** Nothing below this is worth a panel; nothing above it is worth reading. */
const MAX_RESULTS = 7

type Hit = { group: string; href: string; title: string }

/**
 * Everything addressable in the lab, flattened once.
 *
 * Built at module scope: the four sources are static imports, so rebuilding
 * this per keystroke would be recomputing a constant.
 */
const HAYSTACK: Hit[] = [
  ...DOCS_SECTIONS.flatMap((section) =>
    section.groups.flatMap((group) =>
      group.pages.map((page) => ({
        group: section.title,
        href: docsHref(page.id),
        title: page.title,
      })),
    ),
  ),
  ...MOCKUPS.map((entry) => ({
    group: "Mockups",
    href: entry.href,
    title: entry.title,
  })),
  ...REELS.map((entry) => ({
    group: "Reels",
    href: entry.href,
    title: entry.title,
  })),
]

function search(term: string): Hit[] {
  const needle = term.trim().toLowerCase()
  if (!needle) return []

  /* Titles that start with the term first: typing "to" should reach Tooltip
     before it reaches "Empty and zero states", which merely contains a "to". */
  return HAYSTACK.filter((hit) => hit.title.toLowerCase().includes(needle))
    .sort((a, b) => {
      const lead =
        Number(b.title.toLowerCase().startsWith(needle)) -
        Number(a.title.toLowerCase().startsWith(needle))
      return lead || a.title.length - b.title.length
    })
    .slice(0, MAX_RESULTS)
}

/** The keyboard never changes under us, so there is nothing to subscribe to. */
const NEVER_CHANGES = () => () => {}

/**
 * Which modifier to print in the shortcut hint.
 *
 * It depends on the reader's keyboard, which the server cannot know, so the
 * hint is empty until hydration rather than rendering one modifier and
 * correcting itself to the other in front of the reader.
 */
function useModifierKey() {
  return React.useSyncExternalStore(
    NEVER_CHANGES,
    () => (navigator.userAgent.includes("Mac") ? "⌘" : "Ctrl"),
    () => "",
  )
}

export function NavSearch() {
  const router = useRouter()
  const reduced = useReducedMotion()
  const modifier = useModifierKey()

  const [open, setOpen] = React.useState(false)
  const [term, setTerm] = React.useState("")
  const [active, setActive] = React.useState(0)

  const rootRef = React.useRef<HTMLDivElement>(null)
  const inputRef = React.useRef<HTMLInputElement>(null)

  const hits = React.useMemo(() => search(term), [term])

  const close = React.useCallback(() => {
    setOpen(false)
    setTerm("")
    setActive(0)
  }, [])

  /* Opened from the keyboard, because the one thing a search behind an icon
     loses is that you can no longer just start typing at it.

     ⌘F over the browser's own find bar, which is the trade the index made
     before this replaced its field: find-in-page searches the cards already
     on screen, not the pages a query would reach. ⌘K as well, since it costs
     nothing and is what most people try first. */
  React.useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      const key = event.key.toLowerCase()
      if (key !== "f" && key !== "k") return
      if (!event.metaKey && !event.ctrlKey) return

      event.preventDefault()
      setOpen(true)
      inputRef.current?.focus()
      inputRef.current?.select()
    }

    window.addEventListener("keydown", onKey)
    return () => window.removeEventListener("keydown", onKey)
  }, [])

  /* A click anywhere else puts it away. `pointerdown` rather than `click` so it
     closes on the press that starts an interaction elsewhere, not after it. */
  React.useEffect(() => {
    if (!open) return

    const onDown = (event: PointerEvent) => {
      if (!rootRef.current?.contains(event.target as Node)) close()
    }

    window.addEventListener("pointerdown", onDown)
    return () => window.removeEventListener("pointerdown", onDown)
  }, [close, open])

  const go = (hit: Hit) => {
    close()
    router.push(hit.href)
  }

  return (
    <div className="relative shrink-0" ref={rootRef}>
      {/* `clip`, not `hidden`. Both hide the field while it is a 32px square,
          but `overflow: hidden` makes this a scroll container — so focusing
          the input scrolls it, and the browser leaves it scrolled. The field
          then sits a pixel or more to the left of the box clipping it, which
          shaves its left border and its rounded corner and opens a gap on the
          right. `overflow: clip` is not scrollable, so there is nothing for
          focus to shift. */}
      <motion.div
        animate={{ width: open ? EXPANDED : COLLAPSED }}
        className="overflow-clip"
        initial={false}
        transition={
          reduced
            ? { duration: 0 }
            : { damping: 26, mass: 1, stiffness: 300, type: "spring" }
        }
      >
        {/* No focus ring. This sits inside a pill that already draws a ring
            of its own, so the control's own ring lands a second edge a
            hair inside the first. Focus still reads: the field is only this
            wide because it was opened, and it holds the caret. */}
        <InputGroup className="has-[[data-slot=input-group-control]:focus-visible]:border-input has-[[data-slot=input-group-control]:focus-visible]:ring-0">
          <InputGroupAddon>
            <InputGroupButton
              aria-expanded={open}
              aria-label={open ? "Close search" : "Search the lab"}
              onClick={() => {
                if (open) {
                  close()
                  return
                }
                setOpen(true)
                inputRef.current?.focus()
              }}
              size="icon-xs"
            >
              {open ? <ClearIcon /> : <SearchIcon />}
            </InputGroupButton>
          </InputGroupAddon>

          <InputGroupInput
            aria-label="Search the lab"
            onChange={(event) => {
              setTerm(event.target.value)
              setActive(0)
            }}
            onFocus={() => setOpen(true)}
            onKeyDown={(event) => {
              if (event.key === "Escape") {
                close()
                return
              }
              if (!hits.length) return

              if (event.key === "ArrowDown") {
                event.preventDefault()
                setActive((index) => (index + 1) % hits.length)
              }
              if (event.key === "ArrowUp") {
                event.preventDefault()
                setActive((index) => (index - 1 + hits.length) % hits.length)
              }
              if (event.key === "Enter") {
                event.preventDefault()
                const hit = hits[active]
                if (hit) go(hit)
              }
            }}
            placeholder="Search"
            ref={inputRef}
            /* Out of the tab order while it is a 36px sliver — the button
               beside it is the control at that width. */
            tabIndex={open ? 0 : -1}
            value={term}
          />

          {/* The hint the index's field carried. A search folded into an icon
              is a shortcut nobody can discover, so it says so while it is
              open and empty, and gets out of the way once there is a query. */}
          {open && !term ? (
            <InputGroupAddon align="inline-end">
              <Kbd>{modifier}F</Kbd>
            </InputGroupAddon>
          ) : null}
        </InputGroup>
      </motion.div>

      {open && hits.length ? (
        <Card
          className="absolute end-0 top-full z-popover mt-2 w-80 gap-0"
          size="sm"
        >
          {hits.map((hit, index) => (
            <Link
              className={cn(
                "flex items-baseline justify-between gap-3 rounded-md px-2 py-1.5 text-sm",
                index === active ? "bg-muted" : "hover:bg-muted/60",
              )}
              href={hit.href}
              key={`${hit.href}-${hit.title}`}
              onClick={(event) => {
                if (event.metaKey || event.ctrlKey || event.shiftKey) return
                event.preventDefault()
                go(hit)
              }}
              onPointerEnter={() => setActive(index)}
            >
              <span className="truncate">{hit.title}</span>
              <span className="shrink-0 text-xs text-muted-foreground">
                {hit.group}
              </span>
            </Link>
          ))}
        </Card>
      ) : null}
    </div>
  )
}

"use client"

import {
  ArrowLeft02Icon,
  ArrowRight02Icon,
  ArrowUp01Icon,
  ArrowUpRight01Icon,
  BookOpen01Icon,
  Cancel01Icon,
  Copy01Icon,
  Cursor02Icon,
  Link04Icon,
  Search01Icon,
  SourceCodeIcon,
  Tick02Icon,
  TranslateIcon,
} from "@hugeicons/core-free-icons"

import { icon } from "@/components/shared/icon"

/**
 * Icons for the workspace itself — the index and the shell around every
 * mockup. Icons *inside* a mockup live in that mockup's own icons.tsx; this
 * file is only the chrome.
 */
export const BackIcon = icon(ArrowLeft02Icon, "BackIcon")
export const OpenIcon = icon(ArrowRight02Icon, "OpenIcon")
export const SearchIcon = icon(Search01Icon, "SearchIcon")
export const ClearIcon = icon(Cancel01Icon, "ClearIcon")
export const DirectionIcon = icon(TranslateIcon, "DirectionIcon")

/* Beside the ticket ID in a card's footer, so it reads as something that
   leaves the page rather than as another in-page action. */
export const TicketLinkIcon = icon(ArrowUpRight01Icon, "TicketLinkIcon")

/* On the dock at the foot of the index, pointing at the list of surfaces
   that opens above it. */
export const DockIcon = icon(ArrowUp01Icon, "DockIcon")

/* The registry menu on an index card: the trigger, and the copy affordance
   that swaps to a tick once the command is on the clipboard. */
export const RegistryIcon = icon(SourceCodeIcon, "RegistryIcon")
export const CopyIcon = icon(Copy01Icon, "CopyIcon")
export const CopiedIcon = icon(Tick02Icon, "CopiedIcon")

/* On the index header, next to the search field — the way into the design
   system, which has no card in the list below. */
export const RulesIcon = icon(BookOpen01Icon, "RulesIcon")

/* Opens the card's links — the mockup's own URL and the tickets it answers —
   for copying rather than for following. */
export const ShareLinkIcon = icon(Link04Icon, "ShareLinkIcon")

/* The coach. It labels the nav button that replays the walkthrough, and it is
   the glyph the walkthrough parks on whatever control the reader is meant to
   press — the one place in the lab where an icon stands in for a pointer,
   because the pointer is what it is talking about. */
export const PointerIcon = icon(Cursor02Icon, "PointerIcon")

/**
 * Addresses for the design system.
 *
 * Every topic in `DOCS_SECTIONS` is a real URL rather than a client-side tab,
 * so a page can be sent to someone. There are three shapes:
 *
 *   /design-system                       the overview — the five sections
 *   /design-system/<section>             one section — every topic on it
 *   /design-system/<section>/<page>      one topic
 *
 * A section is a real page because the overview cards and the nav menu both
 * open one, and a reader who clicks Patterns wants every pattern, not
 * whichever topic happens to be filed first.
 *
 * Nested rather than flat because a bare `/design-system/data` does not say
 * whether it is the shadcn shelf or something about tables, and a link is read
 * before it is opened. The section segment answers that in the address bar.
 *
 * Derived from `DOCS_SECTIONS` rather than listed again here: the rail and the
 * routes are the same tree, and two copies of it would drift the first time a
 * topic moved between sections.
 */

import {
  DOCS_SECTIONS,
  type DocsPage,
  type DocsSection,
} from "@/lib/design-system/data"

export const DOCS_ROOT = "/design-system"

/** Topic id → the section it is filed under. */
const SECTION_OF = new Map<string, string>(
  DOCS_SECTIONS.flatMap((section) =>
    section.groups.flatMap((group) =>
      group.pages.map((page) => [page.id, section.id] as const),
    ),
  ),
)

/** Topic id → the topic, for turning a slug back into a title. */
const PAGE_OF = new Map<string, DocsPage>(
  DOCS_SECTIONS.flatMap((section) =>
    section.groups.flatMap((group) =>
      group.pages.map((page) => [page.id, page] as const),
    ),
  ),
)

const SECTION_BY_ID = new Map<string, DocsSection>(
  DOCS_SECTIONS.map((section) => [section.id, section]),
)

/** The URL for one topic. */
export function docsHref(id: string): string {
  const sectionId = SECTION_OF.get(id)

  /* A topic with no section cannot be addressed, so it falls back to the
     overview rather than minting a URL that 404s. */
  return sectionId ? `${DOCS_ROOT}/${sectionId}/${id}` : DOCS_ROOT
}

/** The URL for one section's index. */
export function sectionHref(id: string): string {
  return SECTION_BY_ID.has(id) ? `${DOCS_ROOT}/${id}` : DOCS_ROOT
}

/** What a URL resolves to. `page` is null on the overview and on a section. */
export type DocsLocation = {
  section: DocsSection | null
  page: DocsPage | null
  /** What the pane is keyed on: a topic id, a section id, or "" on the
      overview. */
  activeId: string
}

/**
 * Turn the catch-all segments into a location, or null if they name nothing.
 *
 * A null is a 404 rather than a redirect to the overview: a link that silently
 * lands somewhere else is worse than one that says it is broken, because the
 * sender never finds out they sent the wrong thing.
 */
export function resolveDocs(slug?: string[]): DocsLocation | null {
  if (!slug?.length) return { activeId: "", page: null, section: null }

  const [sectionId, pageId, ...rest] = slug
  if (rest.length) return null

  const section = SECTION_BY_ID.get(sectionId)
  if (!section) return null

  if (!pageId) return { activeId: section.id, page: null, section }

  /* The topic has to be under this section, not merely exist: without the
     check, `/design-system/motion/colour` would render the colour page under
     a heading that says Motion. */
  if (SECTION_OF.get(pageId) !== sectionId) return null

  const page = PAGE_OF.get(pageId)
  if (!page) return null

  return { activeId: page.id, page, section }
}

/** Every address the docs answer to, for `generateStaticParams`. */
export function docsParams(): { slug: string[] | undefined }[] {
  return [
    { slug: undefined },
    ...DOCS_SECTIONS.map((section) => ({ slug: [section.id] })),
    ...DOCS_SECTIONS.flatMap((section) =>
      section.groups.flatMap((group) =>
        group.pages.map((page) => ({ slug: [section.id, page.id] })),
      ),
    ),
  ]
}

/**
 * Mock data for DES-199 — the scenario's "Switch voice on language change"
 * setting from the DIS-53 PRD.
 *
 * Languages are the platform's three (EN, AR, UR — `LANGUAGES` in
 * precedent-iso). Personas are agent profiles: one language each, which is the
